/// <summary>
/// Base class for PricingAttribute table <c>InventLocation</c>
/// </summary>
internal abstract class GUPPricingAttributeInventLocation extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
protected InventLocation getTableRecord(Common _pricingObject)
{
    InventLocation inventLocation;

    if (_pricingObject is SalesTable)
    {
        SalesTable salesTable = _pricingObject as SalesTable;

        if (salesTable)
        {
            inventLocation = InventLocation::find(salesTable.custTable_CustAccount().InventLocation);
        }
    }

    return inventLocation;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot, qbdsInventLocation;

    if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(CustTable));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventLocation)))
    {
        qbdsInventLocation = _qbdsMap.lookup(tableStr(InventLocation));
    }
    else
    {
        qbdsInventLocation = qbdsRoot.addDataSource(tableNum(InventLocation));
        qbdsInventLocation.addLink(fieldNum(CustTable, InventLocation), fieldNum(InventLocation, InventLocationId));
        qbdsInventLocation.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventLocation), qbdsInventLocation);
        }
    }

    return qbdsInventLocation;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}

public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5_%6$%7#%8',
        tableStr(SalesTable),
        tableStr(CustTable),
        fieldStr(SalesTable, CustAccount),
        fieldStr(CustTable, AccountNum),
        tableStr(InventLocation),
        fieldStr(CustTable, InventLocation),
        fieldStr(InventLocation, InventLocationId),
        this.getAttributeFieldIdentifier());
}
